isDisabled:
{{ (() => {
  const individual = selIntakeEntityType.selectedOptionValue === "Individual";
  const company = selIntakeEntityType.selectedOptionValue === "Company";
  const member = individual && chkIntakeMember.isChecked;
  const contributor = (individual && chkIntakeContributor.isChecked) ||
    (company && chkCompanyContributor.isChecked);
  const email = (inpIntakeEmail.text || "").trim();
  const phone = (inpIntakePhone.text || "").trim();
  const address = (inpIntakeAddress.text || "").trim();
  const city = (inpIntakeCity.text || "").trim();
  const state = (inpIntakeState.text || "").trim();
  const postal = (inpIntakePostalCode.text || "").trim();
  const hasAnyAddress = [address, city, state, postal].some(Boolean);
  const hasCompleteAddress = [address, city, state, postal].every(Boolean);
  const contactCount = [!!email, !!phone, hasCompleteAddress].filter(Boolean).length;
  const addressValid = !hasAnyAddress || hasCompleteAddress;
  const identityValid = individual
    ? !!(inpIntakeFirstName.text || "").trim() && !!(inpIntakeLastName.text || "").trim()
    : company
      ? !!(inpIntakeCompanyName.text || "").trim()
      : false;
  const contributorReasonValid = !contributor || !!(inpContributorReason.text || "").trim();
  const memberSetupValid = !member || (
    !!selIntakePractitioner.selectedOptionValue &&
    !!selAgreementDelivery.selectedOptionValue &&
    (selAgreementDelivery.selectedOptionValue !== "Digital" ||
      (!!email && !!selAgreementType.selectedOptionValue && !!selAgreementTemplate.selectedOptionValue)) &&
    (selAgreementDelivery.selectedOptionValue !== "Paper" ||
      !!(FilePickerAgreement.files || []).length)
  );
  return !(
    (individual || company) &&
    identityValid &&
    contactCount >= 2 &&
    addressValid &&
    inpIntakeEmail.isValid &&
    inpIntakePhone.isValid &&
    contributorReasonValid &&
    memberSetupValid
  );
})() }}
